import React from 'react';
import { Link } from 'react-router-dom';


const WordCloud = () => {
  return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <h2>WordCloud</h2>
      <img
        src={wordCloudImage}
        alt="wordcloud"
        style={{ width: '10em', height: 'auto', margin: '1rem' }}
      />
      <Link to="/">
        <button style={{ padding: '0.5rem 1rem', fontSize: '1rem' }}>Back</button>
      </Link>
    </div>
  );
};

export default WordCloud;
